INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1301464, 167591, 24454, '<td valign="top">Wow!   That is gorgeous!     The silhouette is perfect.   I love it!</td>', 'Wow!   That is gorgeous!     The silhouette is perfect.   I love it!', '2005-04-18 18:36:13.000000', NULL, 1),
(1301467, 167735, 24454, '<td valign="top">Awww. . . they are so cute. . . and vivid and colorful.   They remind me of the little dancers we have at Fiesta San Antonio going on right now.    Maybe that''s partly why this one appeals to me so much -- that and it''s just a neat picture!   Good luck!</td>', 'Awww. . . they are so cute. . . and vivid and colorful.   They remind me of the little dancers we have at Fiesta San Antonio going on right now.    Maybe that''s partly why this one appeals to me so much -- that and it''s just a neat picture!   Good luck!', '2005-04-18 18:37:24.000000', NULL, 1),
(1301470, 167670, 24454, '<td valign="top">How cute is that!!!    I love your composition!</td>', 'How cute is that!!!    I love your composition!', '2005-04-18 18:37:57.000000', NULL, 1),
(1301471, 166030, 35804, '<td valign="top">The effect used on the face is a little distracting...smart blur filter, some areas seem a little jaggy.</td>', 'The effect used on the face is a little distracting...smart blur filter, some areas seem a little jaggy.', '2005-04-18 18:38:14.000000', NULL, 1),
