(1311798, 167667, 10261, '<td valign="top">Topless. Top-hat. There must be an interesting story here.</td>', 'Topless. Top-hat. There must be an interesting story here.', '2005-04-21 20:23:57.000000', NULL, 1),
(1311803, 165750, 10261, '<td valign="top">Interesting catchlight</td>', 'Interesting catchlight', '2005-04-21 20:25:35.000000', NULL, 1),
