(1311881, 167215, 27812, '<td valign="top">truely adorable... bumping up to 9. You captured the emotion... that one thing so hard  to do.</td>', 'truely adorable... bumping up to 9. You captured the emotion... that one thing so hard  to do.', '2005-04-21 20:58:59.000000', NULL, 1),
(1311916, 166638, 35513, '<td valign="top">I really like the mood of this photo.  Excellently captured.</td>', 'I really like the mood of this photo.  Excellently captured.', '2005-04-21 21:13:32.000000', NULL, 1),
(1311921, 166212, 35513, '<td valign="top">Beautiful shot.</td>', 'Beautiful shot.', '2005-04-21 21:14:59.000000', NULL, 1),
