INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1312617, 166452, 23458, '<td valign="top">What a terrific moment you''ve captured here. Fantastic shot. I''d be tempted to crop a centimetre or two off the top but besides that there is little else I can think of to improve the shot - I don''t even mind the foreground clutter - it provides context for the happy faces.</td>', 'What a terrific moment you''ve captured here. Fantastic shot. I''d be tempted to crop a centimetre or two off the top but besides that there is little else I can think of to improve the shot - I don''t even mind the foreground clutter - it provides context for the happy faces.', '2005-04-22 02:57:47.000000', NULL, 1),
