(1317176, 165678, 4517, '<td valign="top">Great colours, well spotted.</td>', 'Great colours, well spotted.', '2005-04-24 05:56:35.000000', NULL, 1),
(1317177, 167814, 27812, '<td valign="top">nice composition, one most of us will understand.</td>', 'nice composition, one most of us will understand.', '2005-04-24 05:57:04.000000', NULL, 1),
(1317178, 167268, 4517, '<td valign="top">Unusual but works well</td>', 'Unusual but works well', '2005-04-24 05:57:37.000000', NULL, 1),
