(1317186, 167137, 27812, '<td valign="top">Playing guitar can be painful.... or glorious. Love the emotion you captured.</td>', 'Playing guitar can be painful.... or glorious. Love the emotion you captured.', '2005-04-24 05:59:14.000000', NULL, 1),
(1317187, 167781, 31443, '<td valign="top">Cute!</td>', 'Cute!', '2005-04-24 05:59:36.000000', NULL, 1),
(1317188, 167324, 4517, '<td valign="top">Nice lighting, beautiful model.</td>', 'Nice lighting, beautiful model.', '2005-04-24 05:59:50.000000', NULL, 1),
(1317190, 166408, 27812, '<td valign="top">classical beauty, she should not wait for anyone, but rather be waited on ;-) Fabulous background to a spectacular pic. bumping up.</td>', 'classical beauty, she should not wait for anyone, but rather be waited on ;-) Fabulous background to a spectacular pic. bumping up.', '2005-04-24 06:00:45.000000', NULL, 1),
(1317191, 165672, 4517, '<td valign="top">Excellent.10. Great candid shot.</td>', 'Excellent.10. Great candid shot.', '2005-04-24 06:01:08.000000', NULL, 1),
(1317192, 165672, 27812, '<td valign="top">I predict this is a pic that will do well, you captured the moment well... boys will be boys.. Bumping up again... I must be missing home....</td>', 'I predict this is a pic that will do well, you captured the moment well... boys will be boys.. Bumping up again... I must be missing home....', '2005-04-24 06:01:36.000000', NULL, 1),
(1317194, 167447, 27812, '<td valign="top">A little saturation.... perhaps? just lacks the vibrancy one expects from a great pic like this.</td>', 'A little saturation.... perhaps? just lacks the vibrancy one expects from a great pic like this.', '2005-04-24 06:03:03.000000', NULL, 1),
(1317195, 167243, 36299, '<td valign="top">The blurry from motion is neat, but I like it better when its any other part of the body then the head.  personal preference maybe.</td>', 'The blurry from motion is neat, but I like it better when its any other part of the body then the head.  personal preference maybe.', '2005-04-24 06:03:34.000000', NULL, 1),
