(1318071, 167613, 10047, '<td valign="top">Need a little more shutter speed and to shoot with the sun with the camera at a  lower angle (kneeling). Looks like someone is having fun.</td>', 'Need a little more shutter speed and to shoot with the sun with the camera at a  lower angle (kneeling). Looks like someone is having fun.', '2005-04-24 11:26:59.000000', NULL, 1),
(1318074, 167722, 30625, '<td valign="top">Superman now this is a classic. Every little kids dream. The colors are spectacular. The contrast is just wonderful I hope this ribbons well done.</td>', 'Superman now this is a classic. Every little kids dream. The colors are spectacular. The contrast is just wonderful I hope this ribbons well done.', '2005-04-24 11:27:56.000000', NULL, 1),
(1318075, 167539, 25742, '<td valign="top">nice eyes. bit vacant expression tho. good comp /7</td>', 'nice eyes. bit vacant expression tho. good comp /7', '2005-04-24 11:28:00.000000', NULL, 1),
