(1318079, 167279, 25742, '<td valign="top">good comp, seems a little scared tho.</td>', 'good comp, seems a little scared tho.', '2005-04-24 11:29:13.000000', NULL, 1),
(1318080, 167833, 10047, '<td valign="top">Cute model. I would have tried to sharpen the eyes in the post editing, or had her lift her head to get more light on the eyes. Maybe both.</td>', 'Cute model. I would have tried to sharpen the eyes in the post editing, or had her lift her head to get more light on the eyes. Maybe both.', '2005-04-24 11:29:18.000000', NULL, 1),
